import{z as i,x as l,o as e,c as s,q as B,j as o,D as a,d as t,s as r,S as n}from"./chunks/framework.C8m1ZpeB.js";const h=JSON.parse('{"title":"资本管制","description":"","frontmatter":{"title":"资本管制","date":"2026-09-18T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/if-capital-controls.md","filePath":"econ/if-capital-controls.md","lastUpdated":1791063341000}'),d={name:"econ/if-capital-controls.md"};function c(p,E,C,D,F,f){const A=l("Mermaid");return e(),s("div",null,[E[2]||(E[2]=B('<h1 id="资本管制" tabindex="-1">资本管制 <a class="header-anchor" href="#资本管制" aria-label="Permalink to &quot;资本管制&quot;">​</a></h1><div class="epigraph"><p>管制管的是数量，管到的是缝隙：资本像水，闸门抬的是水位、改的是流向——评估管制要看组成与裂缝，不看条文宣布了什么。</p><footer>—— 据 De Gregorio, Edwards and Valdés 2000；Magud, Reinhart and Rogoff 2011；IMF Institutional View 2012 整理</footer></div><p><a href="/econ/if-fx-intervention">上一课</a>把干预收在价格侧：降波动可达、守水平撞基本面。本课补数量侧：当问题不是瞬时波动而是持续流量——涌入期怕热钱堆债务、骤停期怕挤兑外汇——闸门从价格转到数量本身。主干<a href="/econ/capital-controls">资本管制</a>已经给了三角位置与「组成比总量更听使唤」的结论；本课的缺口是<strong>工程细节</strong>：设计空间怎么排、缝隙从哪漏、效力怎么测、开闸与关闸的时机怎么定。后课默认已经读完本课。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>问题有三个，分开才答得清。<strong>楔在哪</strong>：流入还是流出、价格还是数量、按居民身份还是按工具——设计空间是三维的，选错维度等于白管。<strong>漏在哪</strong>：管制是法规，资本是合同与发票，缝隙永远存在且随学习扩大。<strong>怎么证明有效</strong>：总量最不听使唤——Magud–Reinhart–Rogoff 的综述把这一条写成了总结论——于是证明责任移到组成与政策空间上，测什么、怎么测，是方法论不是立场。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>设计空间先排维。第一维方向：流入管制（智利 encaje、巴西 IOF 税）对付涌入期的债务堆积，流出管制（马来西亚 1998 年的兑换冻结与钉住）对付骤停期的挤兑；方向不同，政治含义相反——管流入是防患，管流出是拦逃。第二维形式：价格型（无息准备金、托宾式税）把套利算术留给市场；数量型（额度、审批）直接切断，代价是寻租与错配。第三维对象：FDI、股权、银行信贷、债券分开对待，短期外债的成本抬得最狠——那是骤停时最先断的部分。评估随之定型：不问总量，问组成（期限结构是否拉长）、问在岸离岸分割的深度、问买回的货币空间。智利 encaje 是标准样本：1991 年开征、1992 年提到 30%、锁定期一年，事后研究（De Gregorio–Edwards–Valdés 2000 一线）发现期限被拉长、总量没被压住——这不是失败，是这条渠道的全部。</p>',7)),(e(),o(n,null,{default:a(()=>[r(A,{id:"mermaid-19",class:"mermaid",graph:"flowchart%20TD%0A%20%20SURGE%5B%22%E6%B6%8C%E5%85%A5%E6%BF%80%E5%A2%9E%E6%88%96%E9%AA%A4%E5%81%9C%E5%8E%8B%E5%8A%9B%22%5D%20--%3E%20DES%7B%22%E9%80%89%E6%A5%94%E5%AD%90%22%7D%0A%20%20DES%20--%3E%7C%22%E6%B5%81%E5%85%A5%E9%85%8D%E4%BB%B7%E6%A0%BC%E5%9E%8B%22%7C%20ENQ%5B%22%E6%97%A0%E6%81%AF%E5%87%86%E5%A4%87%E9%87%91%3A%20%E6%99%BA%E5%88%A9%20encaje%22%5D%0A%20%20DES%20--%3E%7C%22%E6%B5%81%E5%87%BA%E9%85%8D%E6%95%B0%E9%87%8F%E5%9E%8B%22%7C%20MAL%5B%22%E5%85%91%E6%8D%A2%E5%86%BB%E7%BB%93%3A%20%E9%A9%AC%E6%9D%A5%E8%A5%BF%E4%BA%9A%201998%22%5D%0A%20%20ENQ%20--%3E%20COMP%5B%22%E7%BB%84%E6%88%90%E5%8F%98%E5%8C%96%3A%20%E6%9C%9F%E9%99%90%E6%8B%89%E9%95%BF%22%5D%0A%20%20MAL%20--%3E%20SEG%5B%22%E5%9C%A8%E5%B2%B8%E7%A6%BB%E5%B2%B8%E5%88%86%E5%89%B2%22%5D%0A%20%20COMP%20--%3E%20GAP%5B%22%E7%BC%9D%E9%9A%99%3A%20%E5%8F%91%E7%A5%A8%E4%B8%8E%E8%A1%8D%E7%94%9F%E5%93%81%22%5D%0A%20%20SEG%20--%3E%20GAP%0A%20%20GAP%20--%3E%20EXIT%5B%22%E5%BC%80%E9%97%B8%E6%97%B6%E6%9C%BA%E4%B8%8E%E9%80%80%E5%87%BA%E8%AE%BE%E8%AE%A1%22%5D%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[t(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=B('<p><span class="marginnote">智利 encaje 对除 FDI 外的流入收无息准备金，1992 年起比率 30%、存央行一年；1998 年亚洲危机后资本匮乏，随之废止。它抬高的是短期债务的价格——组成渠道是真实的，总量渠道不是。</span></p><p><span class="marginnote">数字实例：借 1 年期 100 万美元，encaje 要求 30% 无息存央行一年，机会成本按年利率 8% 算是 2.4 万美元——等于把这笔借款的年成本抬高 2.4 个百分点。锁定期固定一年，若把期限拉到 5 年，同样的成本摊到每年只剩约 0.5 个百分点：楔子天然「劝长避短」。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>机制是楔子与缝隙的赛跑。楔子分割市场：管制生效的直接后果是在岸与离岸价格脱钩，NDF 隐含利率偏离在岸利率（<a href="/quant/irp">量化栏的利率平价</a>的尾段），脱钩幅度是管制强度的事后度量——比法条诚实。缝隙从贸易与合同里漏：高开低开的发票、贸易信贷的提前与错后、跨国公司的内部转移、衍生品的替代头寸；马来西亚 1998 年能在一年内守得住，靠的是离岸林吉特市场被一并关掉，代价是市场多年不敢回来。组成渠道是真实的收益：抬高短期美元债的成本，流入被推向 FDI 与长债，骤停时的断裂面就小——这与<a href="/econ/global-financial-cycle">全球金融周期</a>的两难相接：浮动不绝缘，所以连不钉汇率的国家也需要 CFM，IMF 2012 年的机构观点把这一点写进了官方工具箱，与<a href="/econ/macroprudential">宏观审慎</a>配套使用。不这么做会错在哪：把宣布的条文当实际的楔子；把总量不变读成管制无效；把管制当永久绝缘板——它是买时间的工具，时间花在哪决定成败。</p>',4)),(e(),o(n,null,{default:a(()=>[r(A,{id:"mermaid-32",class:"mermaid",graph:"flowchart%20TD%0A%20%20CTRL%5B%22%E7%AE%A1%E5%88%B6%E9%97%B8%E9%97%A8%EF%BC%9A%E9%99%90%E5%88%B6%E6%9F%90%E7%B1%BB%E8%B7%A8%E5%A2%83%E6%B5%81%22%5D%20--%3E%20SPLIT%5B%22%E5%9C%A8%E5%B2%B8%E4%B8%8E%E7%A6%BB%E5%B2%B8%E4%BB%B7%E6%A0%BC%E8%84%B1%E9%92%A9%22%5D%0A%20%20SPLIT%20--%3E%20MEAS%5B%22NDF%20%E9%9A%90%E5%90%AB%E5%88%A9%E7%8E%87%E5%B7%AE%EF%BC%9A%E5%BC%BA%E5%BA%A6%E7%9A%84%E4%BA%8B%E5%90%8E%E5%BA%A6%E9%87%8F%22%5D%0A%20%20CTRL%20--%3E%20INV%5B%22%E8%99%9A%E5%BC%80%E5%8F%91%E7%A5%A8%EF%BC%9A%E9%AB%98%E5%BC%80%E8%BF%9B%E5%8F%A3%E3%80%81%E4%BD%8E%E5%BC%80%E5%87%BA%E5%8F%A3%22%5D%0A%20%20CTRL%20--%3E%20TC%5B%22%E8%B4%B8%E6%98%93%E4%BF%A1%E8%B4%B7%EF%BC%9A%E6%8F%90%E5%89%8D%E4%BB%98%E6%AC%BE%E4%B8%8E%E9%94%99%E5%90%8E%E6%94%B6%E6%AC%BE%22%5D%0A%20%20CTRL%20--%3E%20DERC%5B%22%E8%A1%8D%E7%94%9F%E5%93%81%EF%BC%9A%E7%94%A8%E4%BA%92%E6%8D%A2%E4%B8%8E%E8%BF%9C%E6%9C%9F%E6%9B%BF%E4%BB%A3%E7%9B%B4%E6%8E%A5%E5%80%9F%E8%B4%B7%22%5D%0A%20%20INV%20--%3E%20LEAK%5B%22%E6%80%BB%E9%87%8F%E7%BB%95%E9%81%93%EF%BC%9A%E9%97%B8%E9%97%A8%E5%8F%AA%E6%94%B9%E6%B5%81%E5%90%91%22%5D%0A%20%20TC%20--%3E%20LEAK%0A%20%20DERC%20--%3E%20LEAK%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[t(" Loading... ",-1)])]),_:1})),E[4]||(E[4]=B('<p><span class="marginnote">术语翻译：「在岸/离岸脱钩」就是同一笔钱在境内外的价格分了家。在岸一年期利率 6%，离岸 NDF 隐含的利率却是 10%——中间 4 个百分点的裂缝，是资本为绕开管制愿意付的「买路钱」，也是外界估计管制强度最诚实的尺子。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>管制不修基本面：财政赤字、银行坏账、汇率高估照旧，它只是把暴露的时点往后推。分配面上，关系户先走，管制的真实承担者常与立法意图相反。信号成本在流出侧最重：关闸是「资本不再回头」的公告，马来西亚之后多年资本流入的溢价里都有这一笔。多边约束真实存在：贸易与投资协定限定可用的楔子；中国式的渐进管理——宏观审慎系数与定价机制——是另一条制度路径，成效与代价仍在记录。最后，效力随学习衰减：同一道闸门，第二次启用时缝隙已经修好；读任何管制研究，先看它测的是启用后第几年。</p><p><span class="marginnote">常见误区：初学者容易拿「资本流入总量没变」证明管制没用。智利 encaje 的经验恰恰相反：总量没压住、期限却拉长了——短期热钱换成 FDI 与长债，骤停时的断裂面小了一截。评估要看它改了什么，不是只看它没压住什么。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>设计空间三维：方向（流入/流出）、形式（价格/数量）、对象（按工具与期限），错维白管。</li><li>评估看组成与分割，不看总量：智利 encaje 拉长期限、压不住总量，这正是渠道的形状。</li><li>楔子制造在岸离岸脱钩，NDF 基差是管制强度的事后度量。</li><li>缝隙从发票、贸易信贷与衍生品漏，效力随学习衰减；马来西亚样本的代价是市场信任。</li><li>管制买时间不修基本面；两难之下它与宏观审慎配套。</li><li>出处：De Gregorio–Edwards–Valdés, <em>JDE</em> 2000；Magud–Reinhart–Rogoff 2011；Ostry 等 IMF 2010/2012；Tobin 1978。</li></ul>',6))])}const m=i(d,[["render",c]]);export{h as __pageData,m as default};
